direct-return:
function Pick(p)
local s:=Upper(p)
return Len(p)
function Main()
? Pick("abcd")
return nil

loop:
function Pick(p)
local n:=0,s:=""
while n<Len(p)
s:=Upper(p)
n++
enddo
return n
function Main()
? Pick("abcd")
return nil

forward-before:
function Pick(p)
local n:=Len(p)
Sink(p)
return n
function Sink(s)
return Upper(s)
function Main()
? Pick("abcd")
return nil
